configfiles.configfile:
set -eu
treefile="\$1"; output="\$2"; files="\$3"; seqfiles="\$4"
seq_ids_file="\$5"; pair_ids_file="\$6"; species_map_file="\$7"

[ -n "\$files" ] || { echo "no pairwise MAFs reached the job" >&2; exit 1; }
[ -n "\$seqfiles" ] || { echo "no FASTA sequences reached the job" >&2; exit 1; }

AWK=gawk
command -v gawk >/dev/null 2>&1 || AWK=awk

mkdir -p work/tmp
## Strip branch lengths (including + exponents), internal bootstrap/node labels after ')',
## trailing ';', and whitespace; convert commas to spaces for tba.
tree=`sed 's/:[-+0-9.eE]*//g; s/)[A-Za-z0-9_.-]*/)/g; s/;//; /^ *\$/d' "\$treefile" | tr '\n' ' ' | sed 's/ //g; s/,/ /g'`
leaves=" `echo "\$tree" | tr '()' '  ' | tr -s ' '` "

nleaves=0
for s in \$leaves; do
    case "\$s" in
        ''|[!A-Za-z]*|*[!A-Za-z0-9_]*|*maf*|*eof*)
            echo "tree leaf \$s cannot go through tba: must be a letter then letters, digits or _, without maf or eof" >&2
            exit 1
            ;;
    esac
    nleaves=`expr \$nleaves + 1`
done
[ "\$nleaves" -ge 2 ] || { echo "tree must have at least 2 leaves, found \$nleaves" >&2; exit 1; }

cat > resolve_and_stage.awk <<'AWK_EOF'
function trim(s) {
    gsub(/^[[:space:]]+|[[:space:]]+$/, "", s)
    return s
}
function valid_species(sp) {
    return (sp ~ /^[A-Za-z][A-Za-z0-9_]*$/ && sp !~ /maf|eof/)
}
function map_species(raw) {
    if (raw in smap) return smap[raw]
    return raw
}
function in_leaves(sp) {
    return (sp in leaf_set)
}
function split_pair(pid,    i, n, sep, seps, pos, a, b, sa, sb, rest) {
    seps[1] = "__"
    seps[2] = "."
    seps[3] = "_"
    for (i = 1; i <= 3; i++) {
        sep = seps[i]
        pos = 1
        while (1) {
            rest = substr(pid, pos)
            n = index(rest, sep)
            if (n == 0) break
            a = substr(pid, 1, pos + n - 2)
            b = substr(pid, pos + n - 1 + length(sep))
            if ((a in known_raw || a in leaf_set) && (b in known_raw || b in leaf_set)) {
                sa = map_species(a)
                sb = map_species(b)
                if (in_leaves(sa) && in_leaves(sb)) {
                    pair_sp1 = sa
                    pair_sp2 = sb
                    return 1
                }
            }
            pos = pos + n
        }
    }
    return 0
}
BEGIN {
    nleaves = split(leaves_str, larr, /[[:space:]]+/)
    for (i = 1; i <= nleaves; i++) {
        if (larr[i] != "") leaf_set[larr[i]] = 1
    }
    if (species_map_file != "") {
        while ((getline line < species_map_file) > 0) {
            gsub(/\r$/, "", line)
            if (line == "" || line ~ /^#/) continue
            nf = split(line, cols, /\t/)
            if (nf >= 2) {
                k = trim(cols[1])
                v = trim(cols[2])
                if (k != "" && v != "") {
                    smap[k] = v
                    known_raw[k] = 1
                }
            }
        }
        close(species_map_file)
    }
    if (mode == "fastas") {
        nf = split(paths_str, paths, /,/)
        ni = 0
        while ((getline line < ids_file) > 0) {
            gsub(/\r$/, "", line)
            line = trim(line)
            if (line == "") continue
            ni++
            ids[ni] = line
        }
        close(ids_file)
        if (ni != nf) {
            printf("sequence_ids count (%d) != sequences count (%d)\n", ni, nf) > "/dev/stderr"
            exit 1
        }
        for (i = 1; i <= nf; i++) {
            raw = ids[i]
            sp = map_species(raw)
            if (!valid_species(sp)) {
                printf("species name %s (from %s) cannot go through tba: must be a letter then letters, digits or _, without maf or eof (supply species_map if needed)\n", sp, raw) > "/dev/stderr"
                exit 1
            }
            if (!in_leaves(sp)) {
                printf("%s (from sequence_id %s) is not in the tree\n", sp, raw) > "/dev/stderr"
                exit 1
            }
            printf("%s\t%s\n", sp, paths[i])
        }
    } else if (mode == "mafs") {
        if (seq_ids_file != "") {
            while ((getline line < seq_ids_file) > 0) {
                gsub(/\r$/, "", line)
                line = trim(line)
                if (line != "") known_raw[line] = 1
            }
            close(seq_ids_file)
        }
        nf = split(paths_str, paths, /,/)
        ni = 0
        while ((getline line < ids_file) > 0) {
            gsub(/\r$/, "", line)
            line = trim(line)
            if (line == "") continue
            ni++
            ids[ni] = line
        }
        close(ids_file)
        if (ni != nf) {
            printf("pairwise_ids count (%d) != pairwise count (%d)\n", ni, nf) > "/dev/stderr"
            exit 1
        }
        for (i = 1; i <= nf; i++) {
            pid = ids[i]
            if (!split_pair(pid)) {
                printf("cannot split pairwise identifier %s into two species in the tree\n", pid) > "/dev/stderr"
                exit 1
            }
            if (pair_sp1 == pair_sp2) {
                printf("skipping self-pair %s\n", pid) > "/dev/stderr"
                continue
            }
            printf("%s\t%s\t%s\n", pair_sp1, pair_sp2, paths[i])
        }
    }
}
AWK_EOF

nsp=0
if [ -n "\$seq_ids_file" ]; then
    "\$AWK" -v mode="fastas" \
        -v leaves_str="\$leaves" \
        -v paths_str="\$seqfiles" \
        -v ids_file="\$seq_ids_file" \
        -v species_map_file="\$species_map_file" \
        -f resolve_and_stage.awk > fasta_plan.tsv
    while IFS='	' read -r sp f; do
        [ -n "\$sp" ] || continue
        if [ -e "work/\$sp" ]; then
            echo "\$sp FASTA is given twice" >&2
            exit 1
        fi
        p="\$sp."
        ## Check whether ALL headers already carry the species prefix; if not, prefix EVERY header unconditionally.
        prefixed=`"\$AWK" -v p="\$p" '/^>/{ n++; if (index(\$1, ">" p) == 1) m++ } END { print (n > 0 && n == m) ? "yes" : "no" }' "\$f"`
        if [ "\$prefixed" = "yes" ]; then
            ln -s "\$f" "work/\$sp"
        else
            exp_bytes=`"\$AWK" -v p="\$p" -v out="work/\$sp" '
                /^>/ { sub(/^>/, ">" p) }
                { print > out; nb += length(\$0) + 1 }
                END { if (close(out) != 0) { print "failed writing " out > "/dev/stderr"; exit 1 }; print nb + 0 }
            ' "\$f"`
            got_bytes=`wc -c < "work/\$sp" | tr -d '[:space:]'`
            if [ "\$got_bytes" != "\$exp_bytes" ]; then
                echo "truncated write staging FASTA for \$sp (expected \$exp_bytes bytes, got \$got_bytes)" >&2
                exit 1
            fi
        fi
        nsp=`expr \$nsp + 1`
    done < fasta_plan.tsv
else
    IFS=','
    for f in \$seqfiles; do
        unset IFS
        sp=`"\$AWK" '/^>/{ sub(/^>/, "", \$1); split(\$1, p, "."); print p[1]; exit }' "\$f"`
        IFS=','
        [ -n "\$sp" ] || continue
        case "\$leaves" in *" \$sp "*) ;; *) echo "\$sp (from FASTA) is not in the tree" >&2; exit 1;; esac
        if [ -e "work/\$sp" ]; then
            echo "\$sp FASTA is given twice" >&2
            exit 1
        fi
        ln -s "\$f" "work/\$sp"
        nsp=`expr \$nsp + 1`
    done
    unset IFS
fi

if [ "\$nsp" -ne "\$nleaves" ]; then
    echo "expected \$nleaves species FASTAs matching tree leaves, staged \$nsp" >&2
    exit 1
fi

n=0
empty=0
if [ -n "\$pair_ids_file" ]; then
    "\$AWK" -v mode="mafs" \
        -v leaves_str="\$leaves" \
        -v paths_str="\$files" \
        -v ids_file="\$pair_ids_file" \
        -v seq_ids_file="\$seq_ids_file" \
        -v species_map_file="\$species_map_file" \
        -f resolve_and_stage.awk > maf_plan.tsv
    while IFS='	' read -r sp1 sp2 f; do
        [ -n "\$sp1" ] && [ -n "\$sp2" ] || continue
        if [ -e "work/\$sp1.\$sp2.sing.maf" ]; then
            echo "\$sp1.\$sp2 is given twice" >&2
            exit 1
        fi
        first_s1=`"\$AWK" '/^s[[:space:]]/{ print \$2; exit }' "\$f"`
        if [ -z "\$first_s1" ]; then
            empty=`expr \$empty + 1`
            continue
        fi
        p1="\$sp1."
        p2="\$sp2."
        ## Detect whether file is already prefixed on first block; stream-validate sort order and prefix unconditionally if bare.
        first_s2=`"\$AWK" '/^s[[:space:]]/{ c++; if (c == 2) { print \$2; exit } }' "\$f"`
        already_prefixed="no"
        case "\$first_s1|\$first_s2" in
            "\$p1"*"|\$p2"*) already_prefixed="yes" ;;
        esac
        exp_bytes=`"\$AWK" -v p1="\$p1" -v p2="\$p2" -v pre="\$already_prefixed" -v out="work/\$sp1.\$sp2.sing.maf" '
            function die(m) { print "multiz_tba: " m > "/dev/stderr"; failed = 1; exit 1 }
            function endblock() {
                if (row != 2) die("block at line " bline " has " row " s line(s), expected 2")
                inblock = 0
            }
            function emit(s) { print s > out; nb += length(s) + 1 }
            function put_prefixed(pref,   lead) {
                match(\$0, /^s +/)
                lead = substr(\$0, 1, RLENGTH)
                emit(lead pref substr(\$0, RLENGTH + 1))
            }
            /^[[:space:]]*$/ {
                if (inblock) endblock()
                if (pre == "no") emit(\$0)
                next
            }
            /^a([[:space:]]|$)/ {
                if (inblock) endblock()
                inblock = 1; row = 0; bline = NR
                if (pre == "no") emit(\$0)
                next
            }
            /^s[[:space:]]/ {
                if (split(\$0, f, " ") != 7) die("s line at line " NR " does not have 7 fields")
                if (row == 0) {
                    q = f[2]
                    if (f[5] != "+") die("target row at line " NR " is on the - strand")
                    if (q != cur) {
                        if (q in done) die("target sequence " q " restarts at line " NR ": input MAF is not sorted")
                        if (cur != "") done[cur] = 1
                        cur = q; last = -1
                    }
                    if (f[3] + 0 < last) die("target start goes backwards at line " NR ": " q " " f[3] " after " last)
                    last = f[3] + 0
                    if (pre == "no") put_prefixed(p1)
                } else if (row == 1) {
                    if (pre == "no") put_prefixed(p2)
                } else {
                    die("block at line " bline " has >2 s lines")
                }
                row++
                next
            }
            { if (pre == "no") emit(\$0) }
            END {
                if (failed) exit 1
                if (inblock) endblock()
                if (pre == "no" && close(out) != 0) die("failed writing " out)
                print nb + 0
            }
        ' "\$f"`
        if [ "\$already_prefixed" = "yes" ]; then
            ln -s "\$f" "work/\$sp1.\$sp2.sing.maf"
        else
            got_bytes=`wc -c < "work/\$sp1.\$sp2.sing.maf" | tr -d '[:space:]'`
            if [ "\$got_bytes" != "\$exp_bytes" ]; then
                echo "truncated write staging MAF for \$sp1.\$sp2 (expected \$exp_bytes bytes, got \$got_bytes)" >&2
                exit 1
            fi
        fi
        n=`expr \$n + 1`
    done < maf_plan.tsv
else
    IFS=','
    for f in \$files; do
        unset IFS
        sp1=`"\$AWK" '/^s /{ split(\$2, p, "."); print p[1]; exit }' "\$f"`
        sp2=`"\$AWK" -v s1="\$sp1" '/^s /{ split(\$2, p, "."); if (p[1] != s1) { print p[1]; exit } }' "\$f"`
        IFS=','
        if [ -z "\$sp1" ] || [ -z "\$sp2" ]; then
            empty=`expr \$empty + 1`
            continue
        fi
        case "\$leaves" in *" \$sp1 "*) ;; *) echo "\$sp1 is not in the tree" >&2; exit 1;; esac
        case "\$leaves" in *" \$sp2 "*) ;; *) echo "\$sp2 is not in the tree" >&2; exit 1;; esac
        if [ -e "work/\$sp1.\$sp2.sing.maf" ]; then echo "\$sp1.\$sp2 is given twice" >&2; exit 1; fi
        ln -s "\$f" "work/\$sp1.\$sp2.sing.maf"
        n=`expr \$n + 1`
    done
    unset IFS
fi

expected=`expr \$nleaves \* \( \$nleaves - 1 \)`
received=`expr \$n + \$empty`
if [ "\$received" -lt "\$expected" ]; then
    echo "expected \$expected ordered pairwise MAFs for \$nleaves species, received \$received (\$n non-empty, \$empty empty)" >&2
    exit 1
fi
[ "\$n" -gt 0 ] || { echo "no non-empty pairwise MAFs found" >&2; exit 1; }
echo "species staged: \$nsp of \$nleaves"
echo "pairwise MAFs staged: \$n of \$expected"
echo "empty pairs skipped: \$empty"
echo "tree: \$tree"
cd work
tba + T="\$PWD/tmp" "\$tree" *.*.sing.maf out.maf > /dev/null
cd ..
mv work/out.maf "\$output"
